(()=>{let e=(()=>{let e=document.querySelectorAll(".article-detail__content figure");return{setEventClick:function(){e.forEach(e=>{e.addEventListener("click",e=>{var t=e.target.dataset.event;try{this[t](e.target)}catch(e){console.log("setEventClick error: ",e)}})})},setWidthAsContainer:t=>{e.forEach(e=>{e.style.width=window.outerWidth-t+"px"})},addCopylink:()=>{e.forEach(e=>{e.insertAdjacentHTML("afterbegin",'<div class="article-detail__content_copylink" data-event="copyCode"></div>')})},copyCode:function(e){var t=e.parentElement.querySelector(".hljs").innerText;navigator.clipboard.writeText(t).then(()=>{this.copyCodeSuccess(e),console.log("Текст успешно скопирован в буфер обмена!")}).catch(function(e){console.error("Ошибка при копировании текста: ",e)})},copyCodeSuccess:function(e){"copyCodeSuccess"!==e.classList[1]&&(e.classList.add("copyCodeSuccess"),this.copyCodeStatusClean(e,"copyCodeSuccess"))},copyCodeStatusClean:function(...e){let t=e[0],o=e[1];setTimeout(()=>{t.classList.remove(o)},3e3)}}})();document.addEventListener("DOMContentLoaded",function(){window.hljs&&hljs.highlightAll(),e.setEventClick(),e.addCopylink()})})();